import images from '../monster-images.json'

// Generated by commands/import-scenario-monsters.js: game => monster => "{art game}/{image}"
export default {
    portrait(game, monster) {
        const image = images[game]?.[monster];
        return image ? `/img/monsters/${image}.jpg` : null;
    },
    thumbnail(game, monster) {
        const image = images[game]?.[monster];
        return image ? `/img/monsters/${image.replace('/', '/thumbs/')}.jpg` : null;
    },
}
